-- 02-approve.sql — approves 3 reviewed extraction(s)
-- Generated by scripts/build-install-sql.js. Safe to run more than once.
-- Contains only public publication text and metadata; no secrets.

-- Reviewer recorded in the database: Claude Sonnet 5.5 (AI-assisted, page-by-page visual review of every imported PDF page, 2026-10-16), authorized by project owner Rey Rodriguez
-- Each statement matches on the exact content fingerprint. If a source was re-imported with different content
-- since it was reviewed, it matches 0 rows and stays unreviewed.

-- fingerprint dc76a020456c…  (67 passages)
-- Approve army-cmf36-dapam600-25-2024-07-19. Run only after reviewing the extraction against the PDF.
update public.reference_sources
set review_status = 'approved', reviewed_by = 'Claude Sonnet 5.5 (AI-assisted, page-by-page visual review of every imported PDF page, 2026-10-16), authorized by project owner Rey Rodriguez', reviewed_at = now(), last_checked_at = coalesce(last_checked_at, now())
where id = 'a494f860-7b94-5225-8353-49f9a654bd1c'
  and content_sha256 = 'dc76a020456cda4091863375d648d8787b3e313ebc9bb30188c1a94ecf843d70'
returning id, title, content_sha256, review_status;

